evaluar &lt;- function(ajuste, nombre) {
  augment(ajuste, datos_test) |&gt;
    metrics(truth = puntaje_prueba, estimate = .pred) |&gt;
    mutate(modelo = nombre)
}

bind_rows(
  evaluar(ajuste_ols, "OLS"),
  evaluar(ajuste_lasso, "LASSO"),
  evaluar(ajuste_ridge, "Ridge"),
  evaluar(ajuste_en, "Elastic Net"),
  evaluar(ajuste_rf, "Random Forest")
) |&gt;
  select(modelo, .metric, .estimate) |&gt;
  pivot_wider(names_from = .metric, values_from = .estimate) |&gt;
