+   unnest_tokens(palabra, texto) |&gt;
+   filter(!str_detect(palabra, "^[0-9]+$")) |&gt;
+   anti_join(stop_es, by = "palabra")
R&gt; 
R&gt; # 2. Matriz documento-término y LDA con k = 5
R&gt; dtm &lt;- tokens_limpios |&gt; count(id, palabra) |&gt; cast_dtm(id, palabra, n)
R&gt; set.seed(123)
R&gt; modelo_lda &lt;- LDA(dtm, k = 5, control = list(seed = 123))
R&gt; 
R&gt; # 3. Tópico dominante de cada documento (gamma)
R&gt; doc_topic &lt;- tidy(modelo_lda, matrix = "gamma") |&gt;
+   group_by(document) |&gt;
+   slice_max(gamma, n = 1, with_ties = FALSE) |&gt;
+   ungroup() |&gt;
+   transmute(id = as.integer(document), topic)
R&gt; 
R&gt; # 4. Mapear cada tópico al tema real más frecuente (para medir accuracy)
R&gt; mapa &lt;- doc_topic |&gt;
+   left_join(select(textos, id, tema), by = "id") |&gt;
+   count(topic, tema) |&gt;
+   group_by(topic) |&gt;
+   slice_max(n, n = 1, with_ties = FALSE) |&gt;
+   ungroup() |&gt;
+   select(topic, tema_lda = tema)
R&gt; 
R&gt; lda_pred &lt;- doc_topic |&gt;
+   left_join(mapa, by = "topic") |&gt;
+   left_join(select(textos, id, tema), by = "id")
R&gt; 
R&gt; # Medir sólo sobre los 20 textos de la muestra (mismo set que los LLMs)
R&gt; accuracy_lda &lt;- lda_pred |&gt;
+   filter(id %in% muestra$id) |&gt;
+   summarise(acc = mean(tema == tema_lda)) |&gt;
+   pull(acc)
R&gt; accuracy_lda

